    ui.tags.head(

        ui.tags.script(
            f"""
            let audioContext;
            let microphone;
            let processor;

            let recording = false;
            let busy = false;

            async function beginCapture(stream) {{

                audioContext =
                    new AudioContext();

                microphone =
                    audioContext.createMediaStreamSource(stream);

                processor =
                    audioContext.createScriptProcessor(
                        2048,
                        1,
                        1
                    );

                microphone.connect(processor);

                processor.connect(
                    audioContext.destination
                );

                recording = true;

                console.log("Recording started");

                const startTime = Date.now();

                processor.onaudioprocess = function(e) {{

                    if (!recording) {{
                        return;
                    }}

                    const input =
                        e.inputBuffer.getChannelData(0);

                    const arr = Array.from(input);

                    Shiny.setInputValue(
                        "audio_chunk",
                        arr,
                        {{priority: "event"}}
                    );

                    const elapsed =
                        (Date.now() - startTime) / 1000;

                    Shiny.setInputValue(
                        "recording_time",
                        elapsed,
                        {{priority: "event"}}
                    );

                    if (elapsed &gt;= {RECORD_SECONDS}) {{

                        recording = false;
                        busy = false;

                        processor.disconnect();
                        microphone.disconnect();

                        stream.getTracks().forEach(
                            track =&gt; track.stop()
                        );

                        console.log("Recording finished");

                        Shiny.setInputValue(
                            "recording_done",
                            Math.random(),
                            {{priority: "event"}}
                        );

                        const btn =
                            document.getElementById("start");

                        if (btn) {{
                            btn.disabled = false;
                        }}
                    }}
                }};
            }}

            function runCountdown(seconds, cd, onDone) {{

                let remaining = seconds;

                cd.textContent =
                    "Get ready... " + remaining;

                const timer = setInterval(function() {{

                    remaining -= 1;

                    if (remaining &gt; 0) {{
                        cd.textContent =
                            "Get ready... " + remaining;
                    }} else {{
                        clearInterval(timer);
                        cd.textContent = "";
                        onDone();
                    }}
                }}, 1000);
            }}

            document.addEventListener(
                "DOMContentLoaded",
                function() {{

                    const btn =
                        document.getElementById("start");

                    const cd =
                        document.getElementById("countdown_display");

                    btn.onclick = async function() {{

                        if (busy) {{
                            return;
                        }}

                        busy = true;
                        btn.disabled = true;

                        try {{

                            const stream =
                                await navigator.mediaDevices.getUserMedia({{
                                    audio: {{
                                        echoCancellation: false,
                                        noiseSuppression: false,
                                        autoGainControl: false
                                    }}
                                }});

                            runCountdown(
                                3,
                                cd,
                                function() {{
                                    beginCapture(stream);
                                }}
                            );

                        }} catch(err) {{

                            busy = false;
                            btn.disabled = false;

                            console.error(err);

                            alert(
                                "Microphone error: " + err
                            );
                        }}
                    }};
                }}
            );
            """
        ),
    ),

    ui.layout_sidebar(

        ui.sidebar(

            ui.input_action_button(
                "start",
                "Record (10 seconds)"
            ),

            ui.tags.div(
                id="countdown_display",
                style=(
                    "font-weight:600; color:#4365E2; "
                    "margin: 4px 0; min-height: 1.2em; "
                    "font-size: 0.95em;"
                ),
            ),

            ui.output_text("status"),

            ui.input_slider(
                "freq_lim",
                "Frequency (Hz)",
                min=50,
                max=4000,
                value=[50, 400],
                step=20,
            ),
            width=260,
        ),

        ui.output_plot("waveform_plot", height="110px"),
        ui.output_plot("spectrogram_plot", height="260px"),
    ),
)

def _envelope_fill(ax, t, x, n_bins=800, color="#4365E2"):
    n = len(x)
    bin_size = max(1, n // n_bins)
    n_full = (n // bin_size) * bin_size
    x_trim = x[:n_full].reshape(-1, bin_size)
    t_trim = t[:n_full].reshape(-1, bin_size)
    mins = x_trim.min(axis=1)
    maxs = x_trim.max(axis=1)
    t_bins = t_trim.mean(axis=1)
    ax.fill_between(t_bins, mins, maxs, color=color, linewidth=0)

def server(input, output, session):

    recorded_audio = reactive.value(
        np.array([], dtype=np.float32)
    )

    recording_complete = reactive.value(False)

    @reactive.effect
    @reactive.event(input.start)
    def _():

        recorded_audio.set(
            np.array([], dtype=np.float32)
        )

        recording_complete.set(False)

    @reactive.effect
    @reactive.event(input.audio_chunk)
    def _():

        if recording_complete.get():
            return

        chunk = np.array(
            input.audio_chunk(),
            dtype=np.float32
        )

        current = recorded_audio.get()

        updated = np.concatenate([
            current,
            chunk
        ])

        updated = updated[:MAX_SAMPLES]

        recorded_audio.set(updated)

    @reactive.effect
    @reactive.event(input.recording_done)
    def _():

        recording_complete.set(True)

    @output
    @render.text
    def status():

        if recording_complete.get():

            seconds = (
                len(recorded_audio.get())
                / SAMPLE_RATE
            )

            return (
                f"Recording complete.\n"
                f"{seconds:.1f} seconds captured."
            )

        try:
            rt = input.recording_time()
        except Exception:
            rt = None

        if rt is None:
            return (
                "Press Record to begin."
            )

        return (
            f"Recording... "
            f"{rt:.1f} sec"
        )

    @output
    @render.plot
    def waveform_plot():

        if not recording_complete.get():

            fig, ax = plt.subplots(figsize=(10, 1.1))

            ax.text(
                0.5,
                0.5,
                "No recording yet",
                ha="center",
                va="center",
            )

            ax.axis("off")

            return fig

        audio = recorded_audio.get()
        t = np.arange(len(audio)) / SAMPLE_RATE

        fig, ax = plt.subplots(figsize=(10, 1.1))
        _envelope_fill(ax, t, audio)
        ax.set_xlim(0, RECORD_SECONDS)
        ax.set_yticks([])
        ax.set_xlabel("Time (s)")
        ax.set_title("Recorded sound wave")

        return fig

    @output
    @render.plot
    def spectrogram_plot():

        if not recording_complete.get():

            fig, ax = plt.subplots(figsize=(10, 2.6))

            ax.text(
                0.5,
                0.5,
                "No recording yet",
                ha="center",
                va="center",
            )

            ax.axis("off")

            return fig

        audio = recorded_audio.get()

        window = 1024
        noverlap = 512

        freqs, times, Sxx = spectrogram(
            audio,
            fs=SAMPLE_RATE,
            nperseg=window,
            noverlap=noverlap,
        )

        Sxx_db = 10 * np.log10(
            Sxx + 1e-10
        )

        fig, ax = plt.subplots(
            figsize=(10, 2.6)
        )

        mesh = ax.pcolormesh(
            times,
            freqs,
            Sxx_db,
            shading="gouraud",
        )

        ax.set_ylim(
            input.freq_lim()[0],
            input.freq_lim()[1]
        )

        ax.set_xlabel("Time (s)")
        ax.set_ylabel("Frequency (Hz)")

        ax.set_title(
            "Spectrogram"
        )

        fig.colorbar(
            mesh,
            ax=ax,
            label="Power (dB)"
        )

        return fig

app = App(app_ui, server)


