SAMPLE_RATE = 44100
RECORD_SECONDS = 10
MAX_SAMPLES = SAMPLE_RATE * RECORD_SECONDS
app_ui = ui.page_fluid(

    ui.tags.head(

        ui.tags.script(
            f"""
            let audioContext;
            let microphone;
            let processor;

            let recording = false;

            async function startRecording() {{

                if (recording) {{
                    return;
                }}

                recording = true;

