                    }}
                }};
            }}

            document.addEventListener(
                "DOMContentLoaded",
                function() {{

                    const btn =
                        document.getElementById("start");

                    btn.onclick = async function() {{

                        try {{

                            await startRecording();

                        }} catch(err) {{

                            console.error(err);

                            alert(
                                "Microphone error: " + err
                            );
                        }}
                    }};
                }}
            );
            """
        ),
    ),

    ui.h2("Interactive Audio Spectrogram"),

    ui.layout_sidebar(

        ui.sidebar(

            ui.input_action_button(
                "start",
                "Record / Re-record"
            ),

            ui.hr(),

            ui.input_slider(
                "freq_lim",
                "Frequency limits (Hz)",
                min=50,
                max=22050,
                value=[50,2000],
