def server(input, output, session):

    # Audio storage
    recorded_audio = reactive.value(
        np.array([], dtype=np.float32)
    )

    recording_complete = reactive.value(False)

    # -------------------------------------------------
    # Reset recording
    # -------------------------------------------------

    @reactive.effect
    @reactive.event(input.start)
    def _():

        recorded_audio.set(
            np.array([], dtype=np.float32)
        )

        recording_complete.set(False)
    # -------------------------------------------------
    # Receive audio chunks
    # -------------------------------------------------
    @reactive.effect
    @reactive.event(input.audio_chunk)
    def _():

        if recording_complete.get():
            return

        chunk = np.array(
            input.audio_chunk(),
            dtype=np.float32
        )

        current = recorded_audio.get()

        updated = np.concatenate([
            current,
            chunk
        ])

        updated = updated[:MAX_SAMPLES]

        recorded_audio.set(updated)

    # -------------------------------------------------
    # Recording complete
    # -------------------------------------------------

    @reactive.effect
    @reactive.event(input.recording_done)
    def _():

        recording_complete.set(True)

    # -------------------------------------------------
    # Status text
    # -------------------------------------------------

    @output
    @render.text
    def status():

        if recording_complete.get():

            seconds = (
                len(recorded_audio.get())
                / SAMPLE_RATE
            )

            return (
                f"Recording complete.\n"
                f"{seconds:.1f} seconds captured."
            )

        rt = input.recording_time()

        if rt is None:
            return (
                "Press Record to begin."
            )

        return (
            f"Recording... "
            f"{rt:.1f} sec"
        )

    # -------------------------------------------------
    # Spectrogram
    # -------------------------------------------------

    @output
    @render.plot
    def spectrogram_plot():

        if not recording_complete.get():

            fig, ax = plt.subplots()

            ax.text(
                0.5,
                0.5,
                "No recording yet",
                ha="center",
                va="center",
            )

            ax.axis("off")

            return fig

        audio = recorded_audio.get()

        window = input.window()

        overlap_fraction = (
            input.overlap() / 100
        )

        noverlap = int(
            window * overlap_fraction
        )

        freqs, times, Sxx = spectrogram(
            audio,
            fs=SAMPLE_RATE,
            nperseg=window,
            noverlap=noverlap,
        )

        # Convert to dB
        Sxx_db = 10 * np.log10(
            Sxx + 1e-10
        )

        fig, ax = plt.subplots(
            figsize=(10, 5)
        )

        mesh = ax.pcolormesh(
            times,
            freqs,
            Sxx_db,
            shading="gouraud",
        )

        # Frequency range
        ax.set_ylim(
            input.freq_lim()[0],
            input.freq_lim()[1]
        )

        # Linear / log scale
        if input.scale() == "log":

            ax.set_yscale("log")

        ax.set_xlabel("Time (s)")
        ax.set_ylabel("Frequency (Hz)")

        ax.set_title(
            "Spectrogram"
        )

        if input.show_colorbar():

            fig.colorbar(
                mesh,
                ax=ax,
                label="Power (dB)"
            )

        return fig

# =====================================================
# APP
# =====================================================

app = App(app_ui, server)



