from shiny import App, ui, reactive, render
import numpy as np
import matplotlib.pyplot as plt
from scipy.signal import spectrogram

# =====================================================
# CONSTANTS
# =====================================================

SAMPLE_RATE = 44100
RECORD_SECONDS = 10
MAX_SAMPLES = SAMPLE_RATE * RECORD_SECONDS

# =====================================================
# UI
# =====================================================

app_ui = ui.page_fluid(

    ui.tags.head(

        ui.tags.script(
            f"""
            let audioContext;
            let microphone;
            let processor;

            let recording = false;

            async function startRecording() {{

                if (recording) {{
                    return;
                }}

                recording = true;

                console.log("Recording started");

                const stream =
                    await navigator.mediaDevices.getUserMedia({{
                        audio: true
                    }});

                audioContext =
                    new AudioContext();

                microphone =
                    audioContext.createMediaStreamSource(stream);

                processor =
                    audioContext.createScriptProcessor(
                        2048,
                        1,
                        1
                    );

                microphone.connect(processor);

                processor.connect(
                    audioContext.destination
                );

                const startTime = Date.now();

                processor.onaudioprocess = function(e) {{

                    if (!recording) {{
                        return;
                    }}

                    const input =
                        e.inputBuffer.getChannelData(0);

                    const arr = Array.from(input);

                    Shiny.setInputValue(
                        "audio_chunk",
                        arr,
                        {{priority: "event"}}
                    );

                    const elapsed =
                        (Date.now() - startTime) / 1000;

                    Shiny.setInputValue(
                        "recording_time",
                        elapsed,
                        {{priority: "event"}}
                    );

                    if (elapsed &gt;= {RECORD_SECONDS}) {{

                        recording = false;

                        processor.disconnect();
                        microphone.disconnect();

                        stream.getTracks().forEach(
                            track =&gt; track.stop()
                        );

                        console.log("Recording finished");

                        Shiny.setInputValue(
                            "recording_done",
                            Math.random(),
                            {{priority: "event"}}
                        );
                    }}
                }};
            }}

            document.addEventListener(
                "DOMContentLoaded",
                function() {{

                    const btn =
                        document.getElementById("start");

                    btn.onclick = async function() {{

                        try {{

                            await startRecording();

                        }} catch(err) {{

                            console.error(err);

                            alert(
                                "Microphone error: " + err
                            );
                        }}
                    }};
                }}
            );
            """
        ),
    ),

    ui.h2("Interactive Audio Spectrogram"),

    ui.layout_sidebar(

        ui.sidebar(

            ui.input_action_button(
                "start",
                "Record / Re-record"
            ),

            ui.hr(),

            ui.input_slider(
                "freq_lim",
                "Frequency limits (Hz)",
                min=50,
                max=22050,
                value=[50,2000],
                step=20,
            ),

            ui.input_select(
                "scale",
                "Frequency Scale",
                choices={
                    "linear": "Linear",
                    "log": "Logarithmic",
                },
                selected="linear",
            ),

            ui.input_slider(
                "window",
                "FFT Window Size",
                min=256,
                max=4096,
                value=1024,
                step=256,
            ),

            ui.input_slider(
                "overlap",
                "Overlap (%)",
                min=0,
                max=95,
                value=50,
                step=5,
            ),

            ui.input_checkbox(
                "show_colorbar",
                "Show Colorbar",
                value=True,
            ),
        ),

        ui.card(
            ui.card_header("Status"),
            ui.output_text_verbatim("status"),
        ),

        ui.card(
            ui.card_header("Spectrogram"),
            ui.output_plot("spectrogram_plot"),
        ),
    ),
)

# =====================================================
# SERVER
# =====================================================

def server(input, output, session):

    # Audio storage
    recorded_audio = reactive.value(
        np.array([], dtype=np.float32)
    )

    recording_complete = reactive.value(False)

    # -------------------------------------------------
    # Reset recording
    # -------------------------------------------------

    @reactive.effect
    @reactive.event(input.start)
    def _():

        recorded_audio.set(
            np.array([], dtype=np.float32)
        )

        recording_complete.set(False)

    # -------------------------------------------------
    # Receive audio chunks
    # -------------------------------------------------

    @reactive.effect
    @reactive.event(input.audio_chunk)
    def _():

        if recording_complete.get():
            return

        chunk = np.array(
            input.audio_chunk(),
            dtype=np.float32
        )

        current = recorded_audio.get()

        updated = np.concatenate([
            current,
            chunk
        ])

        updated = updated[:MAX_SAMPLES]

        recorded_audio.set(updated)

    # -------------------------------------------------
    # Recording complete
    # -------------------------------------------------

    @reactive.effect
    @reactive.event(input.recording_done)
    def _():

        recording_complete.set(True)

    # -------------------------------------------------
    # Status text
    # -------------------------------------------------

    @output
    @render.text
    def status():

        if recording_complete.get():

            seconds = (
                len(recorded_audio.get())
                / SAMPLE_RATE
            )

            return (
                f"Recording complete.\n"
                f"{seconds:.1f} seconds captured."
            )

        rt = input.recording_time()

        if rt is None:
            return (
                "Press Record to begin."
            )

        return (
            f"Recording... "
            f"{rt:.1f} sec"
        )

    # -------------------------------------------------
    # Spectrogram
    # -------------------------------------------------

    @output
    @render.plot
    def spectrogram_plot():

        if not recording_complete.get():

            fig, ax = plt.subplots()

            ax.text(
                0.5,
                0.5,
                "No recording yet",
                ha="center",
                va="center",
            )

            ax.axis("off")

            return fig

        audio = recorded_audio.get()

        window = input.window()

        overlap_fraction = (
            input.overlap() / 100
        )

        noverlap = int(
            window * overlap_fraction
        )

        freqs, times, Sxx = spectrogram(
            audio,
            fs=SAMPLE_RATE,
            nperseg=window,
            noverlap=noverlap,
        )

        # Convert to dB
        Sxx_db = 10 * np.log10(
            Sxx + 1e-10
        )

        fig, ax = plt.subplots(
            figsize=(10, 5)
        )

        mesh = ax.pcolormesh(
            times,
            freqs,
            Sxx_db,
            shading="gouraud",
        )

        # Frequency range
        ax.set_ylim(
            input.freq_lim()[0],
            input.freq_lim()[1]
        )

        # Linear / log scale
        if input.scale() == "log":

            ax.set_yscale("log")

        ax.set_xlabel("Time (s)")
        ax.set_ylabel("Frequency (Hz)")

        ax.set_title(
            "Spectrogram"
        )

        if input.show_colorbar():

            fig.colorbar(
                mesh,
                ax=ax,
                label="Power (dB)"
            )

        return fig

# =====================================================
# APP
# =====================================================

app = App(app_ui, server)




