                                    }}
                                }});

                            runCountdown(
                                3,
                                cd,
                                function() {{
                                    beginCapture(stream);
                                }}
                            );

                        }} catch(err) {{

                            busy = false;
                            btn.disabled = false;

                            console.error(err);

